"proposal": {
    "capability": "deployment.set-probes",
    "target": {"group": "apps", "kind": "Deployment", "namespace": "edge", "name": "api-gateway", "uid": "uid-deployment-api-gateway"},
    "params": {
        "container": "app",
        "liveness": {
            "initialDelaySeconds": 20,
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "Allow application to start before liveness probe timeout",
    "rationale": "The pod failed liveness probe immediately after startup (killed_during_startup=true), but the probe timeout is 1s. Increasing timeout and delay gives the app time to initialize before being probed.",
    "cited_evidence_ids": ["ev-target_events", "ev-pod_states", "ev-rollout_history"],
    "cited_predicates": ["killed_during_startup", "probe_kills", "probe_timeouts"]
